select pg_temp.actor('44003000-0000-4000-8000-000000000041','44003000-0000-4000-8000-000000000031','44003000-0000-4000-8000-000000000021');
select is(jsonb_array_length(public.phase4_list_protected_permissions()),3,'HM list has only scoped admin-school combinations');
select ok(not exists(select 1 from jsonb_array_elements(public.phase4_list_protected_permissions()) r where r ? 'pupilId' or r ? 'personalNumber' or r ? 'protectedIdentity'),'permission list contains no pupil data');
select lives_ok($q$insert into results values ('grant',public.phase4_grant_protected_permission((select id from results where name='admin'),'44003000-0000-4000-8000-000000000111'))$q$,'HM explicitly grants one school');
select is(public.phase4_can_read_protected('44003000-0000-4000-8000-000000000211','44003000-0000-4000-8000-000000000111'),false,'granting HM gains no pupil insight');
select throws_ok($q$select public.phase4_grant_protected_permission((select id from results where name='principal'),'44003000-0000-4000-8000-000000000111')$q$,'42501',null,'recipient must be administrator');
select throws_ok($q$select public.phase4_grant_protected_permission((select id from results where name='admin'),'44003000-0000-4000-8000-000000000121')$q$,'42501',null,'other customer school denied');
select pg_temp.actor((select id from results where name='admin'),'44003000-0000-4000-8000-000000000062','44003000-0000-4000-8000-000000000072');
select is(public.phase4_can_read_protected('44003000-0000-4000-8000-000000000211','44003000-0000-4000-8000-000000000111'),true,'admin can read actual placement with explicit school grant');
select is(public.phase4_can_read_protected('44003000-0000-4000-8000-000000000211','44003000-0000-4000-8000-000000000112',public.app_today()+1),false,'protection does not follow pupil transfer');
